<?php
require_once CAMINHO_RAIZ.'/core/Controller.php';require_once CAMINHO_RAIZ.'/models/Configuracao.php';require_once CAMINHO_RAIZ.'/middleware/AuthMiddleware.php';require_once CAMINHO_RAIZ.'/helpers/SegurancaHelper.php';require_once CAMINHO_RAIZ.'/helpers/AuditoriaHelper.php';
class ConfiguracoesController extends Controller {private Configuracao $model;public function __construct(){(new AuthMiddleware())->exigirPerfil(['super_admin','admin_empresa']);$this->model=new Configuracao();}public function index():void{(($_SESSION['usuario_perfil']??'')==='super_admin')?$this->sistema():$this->empresa();}public function sistema():void{(new AuthMiddleware())->exigirPerfil(['super_admin']);$this->renderizar('configuracoes/sistema',['tituloPagina'=>'Configurações do Sistema','paginaAtiva'=>'configuracoes','configuracoes'=>$this->model->obterTodas(null),'csrf_token'=>SegurancaHelper::gerarTokenCSRF()]);}public function empresa():void{$id=(int)$_SESSION['empresa_id'];$this->renderizar('configuracoes/empresa',['tituloPagina'=>'Configurações da Empresa','paginaAtiva'=>'configuracoes','configuracoes'=>$this->model->obterTodas($id),'csrf_token'=>SegurancaHelper::gerarTokenCSRF()]);}public function guardar():void{if(!SegurancaHelper::validarTokenCSRF($_POST['csrf_token']??'')){$this->redirecionar('configuracoes/index');} $sistema=($_SESSION['usuario_perfil']??'')==='super_admin'&&($_POST['contexto']??'')==='sistema';$id=$sistema?null:(int)$_SESSION['empresa_id'];foreach(($_POST['configuracoes']??[]) as $chave=>$valor){if(!preg_match('/^[a-z0-9_]{2,100}$/',$chave))continue;$tipo=$chave==='smtp_senha'?'secreto':'texto';if($tipo==='secreto'&&$valor!=='')$valor=$this->encriptar($valor);if($valor!==''||$tipo!=='secreto')$this->model->guardar($id,$chave,trim($valor),$tipo);}AuditoriaHelper::registar('configuracao_alterada','configuracoes',null,null,['contexto'=>$sistema?'sistema':'empresa']);definirFlash('sucesso','Configurações guardadas com sucesso.');$this->redirecionar($sistema?'configuracoes/sistema':'configuracoes/empresa');}private function encriptar(string $v):string{$key=hash('sha256',(defined('NOME_SISTEMA')?NOME_SISTEMA:'monana'),true);$iv=random_bytes(16);return base64_encode($iv.openssl_encrypt($v,'AES-256-CBC',$key,OPENSSL_RAW_DATA,$iv));}}
